import{z as s,x as l,o as B,c as d,q as o,j as n,D as e,d as t,s as A,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"回测向量化","description":"","frontmatter":{"title":"回测向量化","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/backtest-vectorization.md","filePath":"quant/backtest-vectorization.md","lastUpdated":1791413859000}'),p={name:"quant/backtest-vectorization.md"};function c(h,a,m,u,D,f){const r=l("Mermaid");return B(),d("div",null,[a[2]||(a[2]=o('<h1 id="回测向量化" tabindex="-1">回测向量化 <a class="header-anchor" href="#回测向量化" aria-label="Permalink to &quot;回测向量化&quot;">​</a></h1><div class="epigraph"><p>把日期 × 品种的矩阵一次算完，换来的是速度；付出去的是事件顺序。向量化合法，当且仅当决策不依赖盘中路径与路径依赖的库存。</p><footer>—— 对照 López de Prado 对回测路径与信息泄漏的讨论；事件驱动回测与向量化回测的工程分界</footer></div><p><a href="/quant/feature-store-research">上一课</a>给出可批量取出的点-in-time 特征。本课的缺口是<strong>回测引擎的计算形状</strong>：向量化（对整张面板做数组运算）对事件驱动（按成交与委托逐条推进）。两者不是品味：T+1、涨跌停、队列、保证金路径在事件引擎里自然，在矩阵里必须显式展开，否则会虚构成交。后课研究日志记录你用了哪一种引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日频截面因子：信号在 \\(t\\) 收盘可知，\\(t+1\\) 开盘或收盘成交，成本用价差加冲击函数，向量化足够——前提是没有「当日买了再卖」、没有涨跌停不可成交、没有融资强制平仓路径。A 股<a href="/quant/cn-tplus1">T+1</a> 把可卖量变成状态，矩阵若只有一个持仓列，会放出非法日内反向。问题是列出决策所依赖的状态维度：若状态能写成「昨日持仓 + 今日信号」且成交规则是批量的，向量化；若依赖盘中簿、部分成交、保证金追缴，必须事件化或至少日频状态机。</p><p>向量化的隐蔽泄漏：用 <code>shift(-1)</code> 拿未来收益当标签却不小心拿来当特征；用全样本 <code>mean</code>；用未来才调整的成分。特征商店降低但不消灭这些，因为回测脚本仍能 join 错。引擎应只暴露 <code>data[t]</code> 与 <code>position[t-1]</code>，拒绝向前看的索引。</p><p><span class="marginnote">术语翻译：「向量化」是把整张「日期 × 品种」大表当成一个数组，一次算完所有格子，像流水线一口气切完整排面包；「事件驱动」则是按市场里发生的事逐条推进，每笔委托、每笔成交、每次涨跌停各走一个分支。前者快，后者能表达「下一步取决于刚才发生了什么」的逻辑。</span></p><h3 id="速度不能为路径依赖买单" tabindex="-1">速度不能为路径依赖买单 <a class="header-anchor" href="#速度不能为路径依赖买单" aria-label="Permalink to &quot;速度不能为路径依赖买单&quot;">​</a></h3><p>组合优化、协方差、行业中性可以在每日截面向量化。执行若假设全部在收盘拍卖以收盘价成交，须与<a href="/quant/closing-auction-design">收盘拍卖</a>或 A 股收盘集合竞价规则一致，否则向量化的「收盘价」不是可成交价。涨跌停锁定应把该日成交量置零或置为可成交方向的配给，而不是仍用收盘价变动当收益。</p>',9)),(B(),n(i,null,{default:e(()=>[A(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%86%B3%E7%AD%96%E4%BE%9D%E8%B5%96%E4%BB%80%E4%B9%88%E7%8A%B6%E6%80%81%3F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%A8%E6%97%A5%E6%8C%81%E4%BB%93%20%2B%20%E4%BB%8A%E6%97%A5%E4%BF%A1%E5%8F%B7%7C%20R%7B%22%E6%88%90%E4%BA%A4%E8%A7%84%E5%88%99%E8%83%BD%E5%90%A6%E6%89%B9%E9%87%8F%E6%8F%8F%E8%BF%B0%3F%22%7D%0A%20%20Q%20--%3E%7C%E7%9B%98%E4%B8%AD%E7%B0%BF%20%2F%20%E9%83%A8%E5%88%86%E6%88%90%E4%BA%A4%20%2F%20%E4%BF%9D%E8%AF%81%E9%87%91%E8%BF%BD%E7%BC%B4%7C%20EV%5B%22%E5%BF%85%E9%A1%BB%E4%BA%8B%E4%BB%B6%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20R%20--%3E%7C%E6%98%AF%3A%20%E5%88%B6%E5%BA%A6%E7%8A%B6%E6%80%81%E5%8F%AF%E5%86%99%E6%88%90%E6%8E%A9%E7%A0%81%7C%20VEC%5B%22%E5%90%91%E9%87%8F%E5%8C%96%E4%BF%A1%E5%8F%B7%20%2B%20%E6%97%A5%E9%A2%91%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20R%20--%3E%7C%E5%90%A6%3A%20%E5%90%8C%E4%B8%80%E6%A0%87%E7%9A%84%E6%97%A5%E5%86%85%E6%9D%A5%E5%9B%9E%7C%20EV%0A%20%20VEC%20--%3E%20AUDIT%5B%22%E4%B8%8E%E4%BA%8B%E4%BB%B6%E5%BC%95%E6%93%8E%E5%AF%B9%E6%8B%8D%3A%20%E6%8D%A2%E6%89%8B%20%2F%20%E8%BF%9D%E8%A7%84%E5%8D%95%20%2F%20%E5%87%80%E6%94%B6%E7%9B%8A%22%5D%0A%20%20EV%20--%3E%20AUDIT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">事件驱动不是自动更真：它可以漏掉公司行动、用错时钟。向量化不是自动更假：日频因子加严格 shift 与 PIT 特征，往往更可审计。选择由对象决定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：信号层向量化（NumPy / pandas / Polars 在日期–品种矩阵上）；成交层用显式状态机：可卖量、保证金、停牌、涨跌停标志。两层之间只传递目标权重与约束掩码。掩码必须来自 \\(t\\) 日可知的制度状态。成本：向量化可用线性或平方根冲击 \\(g(q/V)\\)，但 \\(V\\) 用当时 ADV，且参与率封顶，见<a href="/quant/capacity-participation">容量</a>。</p><p><span class="marginnote">数字实例：单边换手 20%、单边成本 15 个 bp，每日成本约 \\(20\\% \\times 15\\,\\mathrm{bp} = 3\\,\\mathrm{bp}\\)，一年 250 个交易日就是约 7.5 个百分点的拖累。成本函数里 \\(V\\) 用错成全样本均值、或参与率没封顶，年化净值轻轻松松差出一位小数——向量化回测里最先要审的就是成本项。</span></p><p>对拍：同一策略在向量化日频引擎与事件引擎（至少用日频 bar + 状态机）上跑，比较换手、违规单数、净收益。差来自非法成交或拍卖规则，应修向量化，而不是把事件引擎关掉。</p><h3 id="并行与复现" tabindex="-1">并行与复现 <a class="header-anchor" href="#并行与复现" aria-label="Permalink to &quot;并行与复现&quot;">​</a></h3><p>按日期分块并行时，块与块之间不能共享带未来的标准化统计量。随机数与特征版本写入实验元数据。向量化容易「一不小心」用到整表，代码审查应搜 <code>shift(-</code>、全样本 <code>std</code>、以及 merge 时未限制 as-of。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数组运算假设交换律与批量同时性。市场是全序事件。当策略的收益主要来自「同时在收盘对所有股票调仓」这一近似，向量化与真实规则的距离小；当收益来自盘中次序、排队、同一股票来回，距离大到结果改号。A 股涨跌停与 T+1 把许多美股日频论文的向量化模板变成非法动作生成器。</p><p><span class="marginnote">直觉类比：向量化假设所有股票在同一时刻按同一规则同时成交，像全班同时交卷；真实市场是一条排队序列，谁先谁后有后果——你那笔买单本身会移动价格。当策略利润恰恰来自「排队里的位置」时，「同时交卷」的近似就把利润来源本身抹掉了，曲线好看也只是把假设当成了收益。</span></p><p><a href="/quant/matching-engine-arch">撮合核</a>的全序在研究里通常被压成日频；这是有意的降维。降维必须写出来，不能假装仍在谈微观结构 alpha。</p>',11)),(B(),n(i,null,{default:e(()=>[A(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20Feat%5B%22PIT%20%E7%89%B9%E5%BE%81%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20Sig%5B%22%E5%90%91%E9%87%8F%E5%8C%96%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20Sig%20--%3E%20Mask%5B%22%E5%88%B6%E5%BA%A6%E6%8E%A9%E7%A0%81%20T%2B1%20%E6%B6%A8%E8%B7%8C%E5%81%9C%20%E5%81%9C%E7%89%8C%22%5D%0A%20%20Mask%20--%3E%20Pos%5B%22%E7%9B%AE%E6%A0%87%E4%BB%93%E4%BD%8D%22%5D%0A%20%20Pos%20--%3E%20State%5B%22%E6%97%A5%E9%A2%91%E5%BA%93%E5%AD%98%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20State%20--%3E%20PnL%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%94%B6%E7%9B%8A%22%5D%0A%20%20Intraday%5B%22%E4%BE%9D%E8%B5%96%E7%9B%98%E4%B8%AD%E6%AC%A1%E5%BA%8F%22%5D%20--%3E%20Ev%5B%22%E4%BA%8B%E4%BB%B6%E5%BC%95%E6%93%8E%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"边界",tabindex:"-1"},[t("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=E("p",null,"本课不提供用向量化掩盖未来函数以美化曲线的技巧。高频、最优执行、做市必须事件化。GPU 加速不改变泄漏代数，只改变犯错速度。",-1)),a[6]||(a[6]=E("h2",{id:"小结",tabindex:"-1"},[t("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=E("ul",null,[E("li",null,"向量化适合批量日频决策；路径依赖的库存与盘中次序需要状态机或事件引擎。"),E("li",null,"引擎只暴露当时可知输入；与事件引擎对拍以抓非法成交。"),E("li",null,"A 股 T+1 与涨跌停使「单列持仓矩阵」经常非法。"),E("li",null,"出处：López de Prado 对回测泄漏的论述；与本栏制度课的成交规则。")],-1))])}const b=s(p,[["render",c]]);export{C as __pageData,b as default};
